def esc(s):return html.escape(str(s))
def rect(x,y,w,h,fill,stroke='none',r=0,sw=1):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{fill}" stroke="{stroke}" stroke-width="{sw}"/>'
def line(x1,y1,x2,y2,color,w=2,dash=''):return f'<path d="M{x1} {y1}L{x2} {y2}" fill="none" stroke="{color}" stroke-width="{w}"'+(f' stroke-dasharray="{dash}"' if dash else '')+'/>'
def path(d,stroke,sw=2,fill='none'):return f'<path d="{d}" fill="{fill}" stroke="{stroke}" stroke-width="{sw}" stroke-linecap="round" stroke-linejoin="round"/>'
def circle(x,y,r,fill,stroke='none',sw=1):return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{fill}" stroke="{stroke}" stroke-width="{sw}"/>'
def font_name(font):
 return ('DejaVu Serif, '+font) if 'Georgia' in font else ('DejaVu Sans Mono, '+font) if 'Courier' in font else ('DejaVu Sans, '+font)
def txt(x,y,s,size=20,fill='#fff',weight=400,font='Arial, sans-serif',spacing=None):return f'<text x="{x}" y="{y}" fill="{fill}" font-size="{size}" font-family="{font_name(font)}" font-weight="{weight}"'+(f' letter-spacing="{spacing}"' if spacing else '')+f'>{esc(s)}</text>'
def wrapped(x,y,s,width=38,size=22,fill='#fff',weight=400,font='Arial, sans-serif',leading=None,max_px=None):
 lines=textwrap.wrap(s,width)
 if max_px:
  family='DejaVuSerif' if 'Georgia' in font else 'DejaVuSansMono' if 'Courier' in font else 'DejaVuSans'
  f=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/'+family+('-Bold' if weight>=700 else '')+'.ttf',size)
  lines=[];current=''
  for word in s.split():
   trial=(current+' '+word).strip()
   if current and f.getlength(trial)>max_px:lines.append(current);current=word
   else:current=trial
  if current:lines.append(current)
 return ''.join(txt(x,y+i*(leading or size*1.35),t,size,fill,weight,font) for i,t in enumerate(lines))
def icon(kind,x,y,c,s=1):
 p={'backend':'M0 12L-10 22L0 32M24 12L34 22L24 32M17 5L7 39', 'app':'M0 0H25V44H0ZM8 7H17M10 36H15', 'game':'M-6 14Q-11 14 -14 24L-18 38Q-18 46 -10 43L0 35H25L35 43Q43 46 43 38L39 24Q36 14 31 14ZM-3 21V33M-9 27H3M26 24H26.1M32 30H32.1','bot':'M-5 12H31V38H-5ZM13 12V3M8 3H18M3 23H4M22 23H23M6 32H20','web':'M-8 4H38V39H-8ZM-8 14H38M-1 9H0M5 9H6M11 9H12M0 22H29M0 29H17','integration':'M-8 7H8V23H-8ZM22 28H38V44H22ZM8 15H30V28M-8 36H8M0 28V44'}[kind]
 return f'<g transform="translate({x} {y}) scale({s})">{path(p,c,2.4)}</g>'

def specimen(kind,x,y,w,h,d,lang,compact=False):
 fg=d['fg'];ac=d['accent'];mut=d['muted'];card=d['card']; out=rect(x,y,w,h,card,r=12)
 if kind=='backend':
  out+=txt(x+18,y+28,'API / SERVICE',12,mut,700)
